size_t n = internal_key.size();
if (n < 8) return false;
uint64_t num = 0;
const char* p = internal_key.data() + n - 8;
for (int i = 0; i < 8; ++i) {
  num |= (static_cast<uint64_t>(static_cast<unsigned char>(p[i])) << (8 * i));
}
*type = static_cast<uint8_t>(num & 0xFF);
*sequence = num >> 8;
if (*type > static_cast<uint8_t>(leveldb::kTypeValue)) return false;
*user_key = Slice(internal_key.data(), n - 8);
return true;
// END_CODE

